// data/exercises.js - the exercise list (DESIGN 5.2 exercises, 17 C.2).
// Made by a private tool from our own list; do not edit it by hand.
// Ids are frozen slugs: once shipped, an id never changes (static test against fixtures/seed_ids.json).
// The first 39 rows are the starting list. Every later row starts with flags_set false: which
// exercises carry a guard flag is set only by a block file. Names and group words are data.

const DEFAULT_DETAIL = Object.freeze({ machine: 'machine', cable: 'cable', barbell: 'barbell', dumbbell: 'dumbbell', bodyweight: 'body', other: 'other' });

function row(id, name, muscle, equipment, extra) {
  return Object.freeze({
    id, name, muscle, equipment,
    count_label: 'reps',
    weight_steps: null,
    step_default: 5,
    unilateral: false,
    machine: equipment === 'machine',
    no_added_sets: false,
    left_out_of_builder: false,
    flags_set: true,
    link: '',
    notes: '',
    custom: false,
    edited: false,
    muscle_detail: null,
    equipment_detail: DEFAULT_DETAIL[equipment],
    load_kind: equipment === 'bodyweight' ? 'body' : 'external',
    tags: Object.freeze([]),
    ...(extra || {})
  });
}

